            new() { Id = 7, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel's research in quantum electrodynamics informs her teaching of classical electromagnetic theory." },
            new() { Id = 8, DepartmentId = 4, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop critical reading, thinking, and writing skills. Emphasis on argumentative and analytical essays.", Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published author and writing coach who has helped thousands of students find their voice.", IsFeatured = true },
