            new() { Id = 11, DepartmentId = 5, Code = "HIST 250", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Examines political, social, and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois is a specialist in modern French history and European integration studies.", IsFeatured = true },
        };
    }

